architecture.h4_f:
msg = CBOR{v:1၊ စာသား၊ ပြန်ကြားရန်၊ send_at}
ct = AES-GCM-256-Encrypt(k၊ nonce၊ msg၊ aad=room_id)
POST /api/rooms/{id}/messages {ciphertext- hex(ct), nonce- hex}

cryptoWire.h1_f:
pt = CBOR{v:1၊ စာသား၊ ပြန်ကြားရန်?၊ thread_id?၊ ဖော်ပြသည်?၊ send_at}
ct = AES-GCM-256-Encrypt(room_key၊ nonce၊ pt၊ aad=hex(room_id))
ဝါယာကြိုး = CBOR{
  v: ၁၊
  ciphertext: hex(ct), // ပြောင်းလဲနိုင်သော အရှည်
  nonce- hex(12 B)၊
  sender_pseudo- hex(16 B),
  send_at: unix_ms
}

cryptoWire.h5_f:
အပြင်ဘက် = CBOR{
  source_node- hex32၊
  ပစ်မှတ်_အသုံးပြုသူ- int64၊
  inner_ciphertext- ဘိုက်များ၊
  inner_nonce: ဘိုက်၊
  send_at: unix_ms
}
sig = Ed25519-Sign(source_priv၊ အပြင်)
POST /federation/deliver { စာအိတ်- အပြင်၊ ဆိုင်း- hex64 }

auth.h1_f:
POST /api/authentication/register လုပ်ပါ။
  { အသုံးပြုသူအမည်၊ စကားဝှက်၊ x25519_public_key၊ display_name၊ ဖုန်း?၊ အီးမေးလ်?၊ avatar_emoji }

တုံ့ပြန်ချက် 201 ဖန်တီးထားသည်-
  { access_token၊ refresh_token၊ user_id၊ အသုံးပြုသူအမည်၊ ... }

auth.h3_f:
access_token payload-
  { ခွဲ- user_id၊ jti- device_id၊ အမျိုးအစား- "ဝင်ရောက်ခွင့်", exp- ယခု + 15 မိနစ် }
refresh_token payload-
  { sub- user_id၊ jti- device_id၊ typ- "refresh", exp: ယခု + 30d }

HS256- .env မှ node ၏ 64-byte လျှို့ဝှက်ချက်ဖြင့် လက်မှတ်ထိုးခဲ့သည်

auth.h4_f:
register_begin(): challenge = rand(32)
                    ရွေးချယ်စရာများ = { rp.id၊ user.id၊ pubKeyCredParams၊ စိန်ခေါ်မှု }
                    ပြန်လာရွေးချယ်စရာများ

register_finish(အတည်ပြုချက်)-
  TPM / Secure Enclave root CA နှင့် ဆန့်ကျင်သည့် အထောက်အထားကို စိစစ်ပါ။
  သိမ်းဆည်းပါ { credential_id၊ public_key၊ တန်ပြန်- 0 }

auth.h7_f:
POST /api/authentication/qr/begin
  → { nonce: 128-bit hex၊ ttl: 60 }
QR payload = { nonce၊ user_id၊ ဆာဗာ- "https://node.example" }

POST /api/authentication/qr/verify { nonce }
  → စက်အသစ် မှတ်ပုံတင်ပြီးပြီ၊ JWT များ ပြန်လာသည်။

rooms.h6_f:
sender_pseudo = HMAC-SHA256(room_pseudo_salt၊ sender_id)[:16] // 32 hex
ciphertext = AES-GCM-Encrypt(room_key၊ nonce၊ CBOR_payload၊ aad=room_id)

Fan-out frame- { type:"m", room, msg:{id, ct, nonce, sender_pseudo, sent_at} }

files.h2_f:
init POST /api/files/resumable/init {ဖိုင်အမည်၊ အရွယ်အစား၊ chunk_size_hint}
            ← {upload_id၊ chunk_size}
အပိုင်း PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct bytes>
            ← ၂၀၄
အပြီးသတ်ရန် POST /api/files/resumable/{upload_id}/finalise {plain_blake3}
            ← 201 {file_id၊ url}
TTL အကြမ်းထည်- ၂၄ နာရီ

files.h4_f:
deny_list = {
  "application/x-dosexec"၊
  "application/x-sharedlib",
  "application/x-mach-binary",
}
အကယ်၍ deny_list တွင် magic.from_buffer(buf[:1024]) ရှိလျှင်- return 415

presence.h1_f:
ကလိုင်းယင့်- ပထမဆုံးသော့ခတ်ခြင်း → ပေးပို့ရန် {type:"t", state:"start"}
         အခြေအနေမပြောင်းပါက 3 စက္ကန့်စာ ပေးပို့မည်မဟုတ်ပါ။
         နောက်ဆုံးသော့ခတ်ပြီးနောက် 10 စက္ကန့် → ပေးပို့ရန် {type:"t", state:"stop"}
လက်ခံသူ- နောက်ဆုံး "စတင်" ပြီးနောက် "ရပ်တန့်ခြင်း" မရှိတော့ပါက အလိုအလျောက်ရပ်ရန် 10 စက္ကန့်

calls.h1_f:
POST /api/calls/{room_id}/စတင် {ဗီဒီယို၊ အသံ} → call_id
WS ထုတ်လွှင့်မှု {type:"c", type:"invite",call_id}
WS ထုတ်လွှင့်မှု {type:"c", type:"offer",sdp}
WS ထုတ်လွှင့်မှု {type:"c", type:"answer",sdp}
WS ထုတ်လွှင့်မှု {type:"c", kind:"candidate",ice} × N
POST /api/calls/{call_id}/end

federation.h2_f:
စာအိတ် = {
  source_node : hex32၊
  target_user : int64၊
  inner_ciphertext- ဘိုက်များ၊
  inner_nonce : ဘိုက်၊
  send_at : unix_ms၊
}
ဆိုင်းဘုတ် = Ed25519Sign(source_priv၊ CBOR(စာအိတ်))
POST /federation/deliver { စာအိတ်၊ ဆိုင်းဘုတ် }

stealth.h2_f:
ClientHello bytes = chrome_120_template {
  random = ကျပန်း၊
  server_name = ကျွန်ုပ်တို့၏ hostname (သို့မဟုတ် ECH-wrapped)၊
  session_id = ကျွန်ုပ်တို့၏ session id၊
}
JA4 = t13d_xxxx_xxxx_xxxx (လက်ရှိ Chrome တည်ငြိမ်သော ကိုက်ညီမှုများ)

stealth.h4_f:
DoH- POST https://cloudflare-dns.com/dns-query {name- x.vortexx.sol}
ECH- ClientHello.extensions += encrypted_sni(public_key_from_HTTPS_record)
DGA- domain(t) = base32( SHA256(seed ∥ YYYY-MM-DD) )[:16] + ".example"

push.h4_f:
iOS NSE- didReceive(တောင်းဆိုချက်) { decrypt(request.content.userInfo) }
Android FCM- onMessageReceived(remoteMessage) { decrypt(remoteMessage.data) }
ဝဘ် SW- self.addEventListener('push'၊ e => decrypt(e.data))

controller.h2_f:
tool = sign_tool
ထည့်သွင်းမှု = ရင်းမြစ်သစ်ပင်၊ သော့များ/release.key
manifest = {
  ဗားရှင်း- "0.1.0",
  built_at: unix_ms၊
  ဖိုင်များ- [{လမ်းကြောင်း၊ sha256၊ အရွယ်အစား}၊ ...]
}
ဆိုင်းဘုတ် = Ed25519-Sign(release_priv၊ CBOR(မန်နီးဖက်စ်))
output = INTEGRITY.sig.json = {manifest၊ signed_by: pub_hex၊ sig: sig_hex}

bots.h1_f:
ဖန်တီးရန်- POST /api/bots {အသုံးပြုသူအမည်၊ display_name၊ ကုဒ်}
          → {bot_id၊ တိုကင်၊ pubkey}
လုပ်ဆောင်ခြင်း- လုပ်ငန်းစဉ်အတွင်း (node အတွင်းရှိ coroutine)
      OR ပြင်ပ (ရှည်လျားသောစစ်တမ်း /api/bots/{id}/အပ်ဒိတ်များ၊ တိုကင်-auth'd)
မက်ဆေ့ဂျ်- {စာသား၊ လက်မှတ်- Ed25519-Sign(bot_priv၊ canonical_msg)}

bots.h2_f:
on /start {
  "ကြိုဆိုပါတယ်၊ {ctx.first_name}" ကို ထုတ်လွှတ်ပါတယ်။
}
on /add <item> {
  state.list = (state.list သို့မဟုတ် []) + [ctx.args.item]
  "Added: {ctx.args.item}" ကို ထုတ်လွှတ်သည်
}

security.h4_f:
canary.txt (နေ့စဉ်):
  {ရက်စွဲ၊ လက္ခဏာ- Ed25519-Sign(release_priv၊ ရက်စွဲ)}
ဖောက်သည်သည် → ပျက်ကွက်ခြင်း သို့မဟုတ် မမှန်ကန်ကြောင်း ⇒ သံသယဖြစ်ဖွယ် အပေးအယူကို အတည်ပြုသည်။

အရေးပေါ်-
  စီမံခန့်ခွဲသူ POST /api/admin/revoke-all {အကြောင်းပြချက်}
  node ထုတ်လွှင့်မှု {type:"n", event:"compromise", reason}
  ကလိုင်းယင့်များသည် သော့များကို သုတ်ကာ၊ ပြန်လည်စတင်သည့်စထရာကို အတင်းအကျပ်လုပ်သည်။

debugging.h2_f:
နှုန်းဟစ်စတိုဂရမ်များ (လမ်းကြောင်း + နည်းလမ်းတစ်ခု)။
  vortex_http_requests_စုစုပေါင်း{လမ်းကြောင်း၊ နည်းလမ်း၊ အခြေအနေ}
  vortex_http_request_duration_seconds_bucket{လမ်းကြောင်း၊နည်းလမ်း၊le}

websocket တိုင်းထွာများ
  vortex_ws_connections{node}
  vortex_ws_fanout_queue_depth{အခန်း၊အသုံးပြုသူ}

စိတ်ကြိုက်ကောင်တာများ-
  vortex_messages_sent_စုစုပေါင်း{room_type}
  vortex_calls_started_total{kind}

login.h4_f:
အောင်မြင်မှု- 201 + JWT စာအိတ် (မှတ်ပုံတင်ပုံသဏ္ဍာန်တူ)
2FA တွင် လိုအပ်သည်- 200 { "needs_2fa": true } ( JWT မရှိသေးပါ )
ပျက်ကွက်မှု- 401 { "error":"invalid_credentials" }

