fts5.h1_f:
CREATE VIRTUAL TABLE messages_fts USING fts5(
  အကြောင်းအရာ၊ -- သင်္ကေတပြုထားသော ကော်လံ
  room_id UNINDEXED၊
  tokenize = 'unicode61 remove_diacritics 2'
);
မေးမြန်းချက်- SELECT အချင်းများ FROM messages_fts WHERE အကြောင်းအရာ MATCH 'foo'

gravitix.h1_f:
on /start { emit "ကြိုဆိုပါတယ်၊ {ctx.first_name}" }
on /add <item> {
